// frontend/src/i18n/index.js
// Consolidated i18n configuration – single source of truth for all languages.
// Supports: English (en), Arabic (ar), French (fr), Russian (ru), Turkish (tr), German (de)

import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';

// ---------------------------------------------------------------------------
// Shared language metadata – used by every language selector in the app.
// `nativeName` is what appears in the dropdowns (per requirements).
// ---------------------------------------------------------------------------
export const SUPPORTED_LANGUAGES = [
  { code: 'en', nativeName: 'English', flag: '🇬🇧', dir: 'ltr' },
  { code: 'ar', nativeName: 'العربية', flag: '🇪🇬', dir: 'ltr' },
  { code: 'fr', nativeName: 'Français', flag: '🇫🇷', dir: 'ltr' },
  { code: 'ru', nativeName: 'Русский', flag: '🇷🇺', dir: 'ltr' },
  { code: 'tr', nativeName: 'Türkçe', flag: '🇹🇷', dir: 'ltr' },
  { code: 'de', nativeName: 'Deutsch', flag: '🇩🇪', dir: 'ltr' }
];

export const LANGUAGE_CODES = SUPPORTED_LANGUAGES.map(l => l.code);

// The single localStorage key used across the whole app for persistence.
export const LANGUAGE_STORAGE_KEY = 'homelyserv_language';

// ---------------------------------------------------------------------------
// Helper: apply direction (LTR only) + lang attribute to <html>.
// Called once on init and whenever the language changes.
// All languages including Arabic use LTR layout; only text is translated.
// ---------------------------------------------------------------------------
export function applyDocumentDirection(langCode) {
  // Always use LTR layout for all languages - Arabic text only, no layout reversal
  document.documentElement.dir = 'ltr';
  document.documentElement.lang = langCode || 'en';
}

// ---------------------------------------------------------------------------
// Helper: change the language globally, persist it, and update RTL.
// Every selector in the app should call this instead of i18n.changeLanguage
// directly so that persistence + direction stay in sync.
// ---------------------------------------------------------------------------
export function changeLanguageGlobal(langCode) {
  if (!LANGUAGE_CODES.includes(langCode)) {
    console.warn(`[i18n] Unsupported language code: ${langCode}`);
    return;
  }
  i18n.changeLanguage(langCode);
  localStorage.setItem(LANGUAGE_STORAGE_KEY, langCode);
  applyDocumentDirection(langCode);
}

